import type {Metadata} from 'next';
import LegalPage from '@/components/LegalPage';
export const metadata:Metadata={title:'Politique de confidentialité',description:'Informations sur le traitement des données personnelles sur le site Marghera Venice Apartments.',alternates:{canonical:'/fr/privacy-policy',languages:{'it-IT': '/privacy-policy', 'en-GB': '/en/privacy-policy', 'de-DE': '/de/privacy-policy', 'fr-FR': '/fr/privacy-policy', 'es-ES': '/es/privacy-policy', 'zh-CN': '/zh/privacy-policy', 'x-default': '/privacy-policy'}},openGraph:{title:'Politique de confidentialité',description:'Informations sur le traitement des données personnelles sur le site Marghera Venice Apartments.',url:'/fr/privacy-policy',locale:'fr_FR',type:'website',images:['/images/home-rialto-vincenzo-landino.webp']},twitter:{card:'summary_large_image',title:'Politique de confidentialité',description:'Informations sur le traitement des données personnelles sur le site Marghera Venice Apartments.',images:['/images/home-rialto-vincenzo-landino.webp']}};
const sections=[{'title': 'Responsable et contacts', 'text': 'Le responsable du site et du traitement des données reçues via les canaux indiqués est Marghera Venice Apartments.\nContact : +39 351 446 2261 · info@margheraveniceapartments.com.'}, {'title': 'Données et finalités', 'text': 'La consultation du site peut entraîner le traitement de données techniques nécessaires à la sécurité, à l’affichage des pages et au fonctionnement du service par le fournisseur d’hébergement/CDN. Le site ne comporte pas de formulaire de contact interne. Si vous nous contactez par téléphone, e-mail, WhatsApp ou WeChat, nous traitons les informations fournies afin de répondre à votre demande, fournir des informations sur l’hébergement et, le cas échéant, prendre des mesures précontractuelles ou gérer votre séjour.'}, {'title': 'Base juridique', 'text': 'Les demandes concernant disponibilités, réservations et séjours sont traitées afin de prendre des mesures précontractuelles à votre demande ou d’exécuter la relation contractuelle. Les données techniques strictement nécessaires sont traitées sur la base de l’intérêt légitime à maintenir un site sûr et opérationnel.'}, {'title': 'Destinataires et services externes', 'text': 'Les données peuvent être traitées par les prestataires techniques nécessaires au fonctionnement du site et, lorsque vous donnez votre consentement, par Google pour Google Analytics 4. Uniquement lorsque vous ouvrez les liens correspondants, des services externes que vous activez, tels que WhatsApp, WeChat, Instagram, Facebook ou des sites d’information liés, peuvent également traiter des données. Ces services appliquent leurs propres politiques.'}, {'title': 'Analytics et consentement', 'text': 'Avec votre consentement, nous utilisons Google Analytics 4 afin d’obtenir des statistiques agrégées sur l’utilisation du site, notamment les pages vues et certaines interactions comme les clics sur WhatsApp ou les liens e-mail. La balise Analytics n’est pas chargée avant votre consentement et les fonctions publicitaires restent désactivées. Vous pouvez modifier ou retirer votre choix via les préférences cookies dans le pied de page.'}, {'title': 'Conservation', 'text': 'Les données de demande sont conservées le temps nécessaire au traitement du contact et, si une réservation ou une obligation légale en découle, pendant les durées imposées par la réglementation applicable. Les données techniques de sécurité sont conservées uniquement le temps nécessaire et selon les paramètres du prestataire technique.'}, {'title': 'Vos droits', 'text': 'Dans les cas prévus par le règlement (UE) 2016/679, vous pouvez demander accès, rectification, effacement, limitation, opposition et portabilité en utilisant les coordonnées ci-dessus. Vous pouvez également introduire une réclamation auprès de l’autorité de contrôle compétente.'}, {'title': 'Mises à jour', 'text': 'Cette politique est mise à jour si les fonctions du site, les prestataires techniques ou les traitements évoluent. Dernière mise à jour : 21 août 2026.'}];
export default function Page(){return <LegalPage lang='fr' title='Politique de confidentialité' eyebrow='Information' subtitle='Comment les données personnelles sont traitées lors de la consultation du site ou d’un contact via les canaux indiqués.' sections={sections}/>;}
